    role_required=False,
    add_details=False,
):
    qs = (
        OrganizationUser.objects.filter(
            organization__users=user_id, organization__slug=organization_slug
        )
        ...
    )
    if team_slug:
        qs = qs.filter(teams__slug=team_slug)
